# strings + url-decoded + zlib streams
found = set()
def scan(b, label):
    for m in re.finditer(rb'[ -~]{4,}', b):
        s = m.group().decode()
        u = unquote(s)
        if 'flag' in s.lower() or re.search(r'[0-9a-f]{64}', u, re.I):
            found.add((label, s[:300]))
    for m in re.finditer(rb'FLAG\{[0-9a-fA-F]{64}\}', b):
        found.add((label, m.group().decode()))
scan(d, 'raw')
# zlib decompress every offset
for off in range(8, min(len(d), 4000000), 1):
    try:
        out = zlib.decompressobj().decompress(d[off:off+9000000])
        if len(out) > 1000: scan(out, f'zlib@{off}')
    except Exception:
        pass
print(list(found)[:20] or 'no hits')
